import os
import sys
import unittest

# Ensure project modules importable
ROOT = os.path.dirname(__file__)
sys.path.insert(0, ROOT)
sys.path.insert(0, os.path.join(ROOT))

from main import Instance
from table import Table
from request import Atom, Head, Query


def make_table(name, columns, rows):
    t = Table(name)
    t.columns = list(columns)
    t.rows = [tuple(r) for r in rows]
    return t


class YannakakisTests(unittest.TestCase):
    def run_query(self, tables, head, atoms):
        inst = Instance()
        for t in tables:
            inst.add_table(t)

        q = Query(head, *atoms)
        res = inst.query(q)

        # return columns and set of rows for comparison
        return tuple(res.columns), set(res.rows)

    def test_single_atom_projection(self):
        t = make_table('R', ['c1', 'c2'], [(1, 2), (3, 4)])
        head = Head('q', 'x')
        a = Atom('R', 'x', 'y')

        cols, rows = self.run_query([t], head, [a])

        self.assertEqual(cols, head.variables)
        self.assertEqual(rows, {(1,), (3,)})

    def test_two_atom_join(self):
        A = make_table('A', ['c1', 'c2'], [(1, 100), (2, 200)])
        B = make_table('B', ['c1', 'c2'], [(100, 'a'), (200, 'b')])

        head = Head('q', 'x', 'z')
        a1 = Atom('A', 'x', 'y')
        a2 = Atom('B', 'y', 'z')

        cols, rows = self.run_query([A, B], head, [a1, a2])

        self.assertEqual(cols, head.variables)
        self.assertEqual(rows, {(1, 'a'), (2, 'b')})

    def test_chain_three_atoms(self):
        T1 = make_table('T1', ['c1', 'c2'], [(1, 10), (2, 20)])
        T2 = make_table('T2', ['c1', 'c2'], [(10, 100), (20, 200)])
        T3 = make_table('T3', ['c1', 'c2'], [(100, 'z1'), (200, 'z2')])

        head = Head('q', 'a', 'd')
        a1 = Atom('T1', 'a', 'b')
        a2 = Atom('T2', 'b', 'c')
        a3 = Atom('T3', 'c', 'd')

        cols, rows = self.run_query([T1, T2, T3], head, [a1, a2, a3])

        self.assertEqual(cols, head.variables)
        self.assertEqual(rows, {(1, 'z1'), (2, 'z2')})

    def test_with_underscore_columns(self):
        S1 = make_table('S1', ['c1', 'c2', 'c3'], [('x1', 'ignore', 'y1'), ('x2', 'ignore', 'y2')])
        S2 = make_table('S2', ['c1', 'c2', 'c3'], [('y1', 'z1', 'i1'), ('y2', 'z2', 'i2')])

        head = Head('q', 'x', 'z')
        a1 = Atom('S1', 'x', '_', 'y')
        a2 = Atom('S2', 'y', 'z', '_')

        cols, rows = self.run_query([S1, S2], head, [a1, a2])

        self.assertEqual(cols, head.variables)
        self.assertEqual(rows, {('x1', 'z1'), ('x2', 'z2')})

    def test_empty_result(self):
        A = make_table('A', ['c1', 'c2'], [(1, 10)])
        B = make_table('B', ['c1', 'c2'], [(20, 'x')])

        head = Head('q', 'x', 'z')
        a1 = Atom('A', 'x', 'y')
        a2 = Atom('B', 'y', 'z')

        cols, rows = self.run_query([A, B], head, [a1, a2])

        self.assertEqual(cols, head.variables)
        self.assertEqual(rows, set())

    def test_large_tables_join(self):
        A = make_table('A', ['c1', 'c2'], [(i, i) for i in range(50)])
        B = make_table('B', ['c1', 'c2'], [(i, i * 10) for i in range(50)])

        head = Head('q', 'x', 'z')
        a1 = Atom('A', 'x', 'y')
        a2 = Atom('B', 'y', 'z')

        cols, rows = self.run_query([A, B], head, [a1, a2])

        self.assertEqual(cols, head.variables)
        expected = {(i, i * 10) for i in range(50)}
        self.assertEqual(rows, expected)

    def test_duplicate_rows(self):
        A = make_table('A', ['c1', 'c2'], [(1, 100), (1, 100), (2, 200)])
        B = make_table('B', ['c1', 'c2'], [(100, 'a'), (100, 'a'), (200, 'b')])

        head = Head('q', 'x', 'z')
        a1 = Atom('A', 'x', 'y')
        a2 = Atom('B', 'y', 'z')

        cols, rows = self.run_query([A, B], head, [a1, a2])

        self.assertEqual(cols, head.variables)
        self.assertEqual(rows, {(1, 'a'), (2, 'b')})

    def test_branching_join(self):
        # Centre table with a key joining two children (branching tree)
        C = make_table('C', ['c1', 'c2'], [(1, 'v1'), (2, 'v2'), (3, 'v3')])
        L = make_table('L', ['c1', 'c2'], [('v1', 'la'), ('v2', 'lb'), ('v2', 'lb2')])
        R = make_table('R', ['c1', 'c2'], [('v1', 'ra'), ('v2', 'rb')])

        head = Head('q', 'k', 'a', 'b')
        a1 = Atom('C', 'k', 'v')
        a2 = Atom('L', 'v', 'a')
        a3 = Atom('R', 'v', 'b')

        cols, rows = self.run_query([C, L, R], head, [a1, a2, a3])

        expected = {(1, 'la', 'ra'), (2, 'lb', 'rb'), (2, 'lb2', 'rb')}
        self.assertEqual(cols, head.variables)
        self.assertEqual(rows, expected)


